/**
 * Information about a cached connection.
 */
public struct FfiConnectionInfo {
    /**
     * Hex-encoded identity fingerprint of the remote peer.
     */
    public var fingerprint: String
    /**
     * Optional human-readable name for the connection.
     */
    public var name: String?
    /**
     * Unix timestamp (seconds) when the connection was first cached.
     */
    public var cachedAt: UInt64
    /**
     * Unix timestamp (seconds) of the last successful connection.
     */
    public var lastConnectedAt: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Hex-encoded identity fingerprint of the remote peer.
         */fingerprint: String, 
        /**
         * Optional human-readable name for the connection.
         */name: String?, 
        /**
         * Unix timestamp (seconds) when the connection was first cached.
         */cachedAt: UInt64, 
        /**
         * Unix timestamp (seconds) of the last successful connection.
         */lastConnectedAt: UInt64) {
        self.fingerprint = fingerprint
        self.name = name
        self.cachedAt = cachedAt
        self.lastConnectedAt = lastConnectedAt
    }
}



extension FfiConnectionInfo: Equatable, Hashable {
    public static func ==(lhs: FfiConnectionInfo, rhs: FfiConnectionInfo) -> Bool {
        if lhs.fingerprint != rhs.fingerprint {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.cachedAt != rhs.cachedAt {
            return false
        }
        if lhs.lastConnectedAt != rhs.lastConnectedAt {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(fingerprint)
        hasher.combine(name)
        hasher.combine(cachedAt)
        hasher.combine(lastConnectedAt)
    }
}


