        /**
         * Optional human-readable name for the connection.
         */name: String?, 
        /**
         * Unix timestamp (seconds) when the connection was first cached.
         */cachedAt: UInt64, 
        /**
         * Unix timestamp (seconds) of the last successful connection.
         */lastConnectedAt: UInt64, 
        /**
         * Opaque transport state bytes — store and return as-is.
         */transportState: Data?) {
        self.fingerprint = fingerprint
        self.name = name
        self.cachedAt = cachedAt
        self.lastConnectedAt = lastConnectedAt
        self.transportState = transportState
    }
}



extension FfiStoredConnection: Equatable, Hashable {
    public static func ==(lhs: FfiStoredConnection, rhs: FfiStoredConnection) -> Bool {
        if lhs.fingerprint != rhs.fingerprint {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.cachedAt != rhs.cachedAt {
            return false
        }
        if lhs.lastConnectedAt != rhs.lastConnectedAt {
            return false
        }
        if lhs.transportState != rhs.transportState {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(fingerprint)
        hasher.combine(name)
        hasher.combine(cachedAt)
        hasher.combine(lastConnectedAt)
        hasher.combine(transportState)
    }
}


