/**
 * Audit event emitted by the UserClient for security-relevant actions.
 *
 * All identity fingerprints are hex-encoded strings.
 */

public enum FfiAuditEvent {
    
    /**
     * A new remote device was accepted as trusted.
     */
    case connectionEstablished(remoteIdentity: String, remoteName: String?, connectionType: FfiConnectionType
    )
    /**
     * A previously-paired device reconnected and refreshed transport keys.
     */
    case sessionRefreshed(remoteIdentity: String
    )
    /**
     * A new connection attempt was rejected during fingerprint verification.
     */
    case connectionRejected(remoteIdentity: String
    )
    /**
     * A remote device sent a credential request (pending approval).
     */
    case credentialRequested(query: FfiCredentialQuery, remoteIdentity: String, requestId: String
    )
    /**
     * A credential request was approved and sent.
     */
    case credentialApproved(query: FfiCredentialQuery, domain: String?, remoteIdentity: String, requestId: String, credentialId: String?
    )
    /**
     * A credential request was denied.
     */
    case credentialDenied(query: FfiCredentialQuery, domain: String?, remoteIdentity: String, requestId: String, credentialId: String?
    )
}


